    assert Arrays.equals(solution.slowestKey(new int[]{50,70,80,90}, "abcd"), a);
    assert Arrays.equals(solution.slowestKey(new int[]{9,29,49,50}, "cbcd"), c);
    assert Arrays.equals(solution.slowestKey(new int[]{10,15,20,25,30}, "aabcd"), a);
